/**
 * /utils/index.js
 * ---------------------------------------------------------------------------
 * Các hàm tiện ích dùng chung toàn project.
 */

/** Format ngày -> dd/MM/yyyy */
export const formatDate = (value, separator = '/') => {
  if (!value) return ''
  const d = new Date(value)
  if (Number.isNaN(d.getTime())) return ''
  const pad = (n) => String(n).padStart(2, '0')
  return [pad(d.getDate()), pad(d.getMonth() + 1), d.getFullYear()].join(separator)
}

/** Format ngày giờ -> dd/MM/yyyy HH:mm */
export const formatDateTime = (value) => {
  if (!value) return ''
  const d = new Date(value)
  if (Number.isNaN(d.getTime())) return ''
  const pad = (n) => String(n).padStart(2, '0')
  return `${formatDate(d)} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

/** Format số -> 1.234.567 */
export const formatNumber = (value, decimals = 0) => {
  const n = Number(value)
  if (Number.isNaN(n)) return '0'
  return n.toLocaleString('vi-VN', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  })
}

/** Format tiền tệ VND */
export const formatCurrency = (value) => `${formatNumber(value)} đ`

/** Rút gọn chuỗi dài */
export const truncate = (str = '', max = 50) =>
  str.length > max ? `${str.slice(0, max)}...` : str

/** Debounce */
export const debounce = (fn, delay = 300) => {
  let timer = null
  return (...args) => {
    clearTimeout(timer)
    timer = setTimeout(() => fn(...args), delay)
  }
}

/** Deep clone đơn giản */
export const clone = (obj) => JSON.parse(JSON.stringify(obj ?? null))

/** Bỏ các key rỗng khỏi object (dùng cho query params) */
export const cleanParams = (obj = {}) =>
  Object.fromEntries(
    Object.entries(obj).filter(
      ([, v]) => v !== '' && v !== null && v !== undefined,
    ),
  )

/** Sinh id ngẫu nhiên */
export const uuid = () =>
  `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`

/** Đọc / ghi localStorage có prefix */
const PREFIX = 'reactjs_sample_'
export const storage = {
  get: (key, defaultValue = null) => {
    try {
      const raw = localStorage.getItem(PREFIX + key)
      return raw ? JSON.parse(raw) : defaultValue
    } catch {
      return defaultValue
    }
  },
  set: (key, value) => localStorage.setItem(PREFIX + key, JSON.stringify(value)),
  remove: (key) => localStorage.removeItem(PREFIX + key),
  clear: () => {
    Object.keys(localStorage)
      .filter((k) => k.startsWith(PREFIX))
      .forEach((k) => localStorage.removeItem(k))
  },
}

/** Tải 1 blob thành file */
export const downloadBlob = (blob, fileName = 'file') => {
  const url = window.URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = fileName
  a.click()
  window.URL.revokeObjectURL(url)
}

/** Lấy base path hiện tại (đọc từ vite.config.js qua import.meta.env.BASE_URL) */
export const getBasePath = () => import.meta.env.BASE_URL || '/'

export default {
  formatDate,
  formatDateTime,
  formatNumber,
  formatCurrency,
  truncate,
  debounce,
  clone,
  cleanParams,
  uuid,
  storage,
  downloadBlob,
  getBasePath,
}
