/**
 * /src/App.jsx
 * ---------------------------------------------------------------------------
 * Component gốc: cấu hình theme + locale Ant Design + gắn router.
 * Locale của Ant Design được đồng bộ theo ngôn ngữ đang chọn (i18n).
 */

import React from 'react'
import { ConfigProvider, App as AntApp, theme as antdTheme } from 'antd'
import viVN from 'antd/locale/vi_VN'
import enUS from 'antd/locale/en_US'
import zhTW from 'antd/locale/zh_TW'

import { AppRouter } from '@/router'
import { useI18n } from '@/lang'
import { useTheme } from '@/utils/theme'

// map ngôn ngữ của app -> locale của Ant Design
const ANT_LOCALES = {
  vi_VN: viVN,
  en_US: enUS,
  zh_TW: zhTW,
}

const App = () => {
  const { locale } = useI18n()
  const { isDark } = useTheme()

  return (
    <ConfigProvider
      locale={ANT_LOCALES[locale] || viVN}
      theme={{
        algorithm: isDark ? antdTheme.darkAlgorithm : antdTheme.defaultAlgorithm,
        token: {
          colorPrimary: isDark ? '#3b82f6' : '#2563eb',
          colorInfo: isDark ? '#22d3ee' : '#06b6d4',
          borderRadius: 10,
        },
      }}
    >
      <AntApp>
        <AppRouter />
      </AntApp>
    </ConfigProvider>
  )
}

export default App
