/* =========================================================================
 *  2. GUARD  (giống router.beforeEach của vue-router)
 * ========================================================================= */

/**
 * Gộp meta của cả chuỗi route cha -> con (con ghi đè cha).
 * @param {Array} matched  mảng route record từ cha xuống con
 */
export const mergeMeta = (matched = []) =>
  matched.reduce((acc, r) => Object.assign(acc, r.meta || {}), {})

/**
 * Xác định `requiresAuth` HIỆU LỰC cho route hiện tại (đi từ con lên cha):
 *  - Nếu CHÍNH route đó có khai báo `requiresAuth` -> dùng giá trị đó
 *    (kể cả `false` — con được phép mở lại route cha đang yêu cầu đăng nhập).
 *  - Nếu route đó KHÔNG khai báo -> lấy theo route CHA gần nhất có khai báo.
 *  - Không route nào trong chuỗi khai báo -> false.
 *
 * @param {Array} matched mảng route record từ cha xuống con
 */
export const resolveRequiresAuth = (matched = []) => {
  for (let i = matched.length - 1; i >= 0; i--) {
    const value = matched[i]?.meta?.requiresAuth
    if (value !== undefined) return !!value
  }
  return false
}

/**
 * Chạy guard cho CẢ CHUỖI route cha -> con (giống vue-router).
 *
 * LƯU Ý: guard được gọi MỘT LẦN với meta đã gộp của cả chuỗi, KHÔNG gọi lặp
 * cho từng record. Nếu gọi lặp, route cha khai báo `requiresAuth: true` sẽ
 * chặn luôn route con đã khai báo `requiresAuth: false` — sai với quy ước
 * "con ghi đè cha". `requiresAuth` hiệu lực được xét theo hướng con -> cha
 * trong resolveRequiresAuth.
 *
 * @returns {true|object} true nếu cho đi tiếp, ngược lại là location cần chuyển tới
 */
export const runGuards = (matched, to) => {
  const meta = mergeMeta(matched)
  return beforeEach({ ...to, matched, meta }, {})
}

export const beforeEach = (to, from) => {
  // cập nhật title (dịch theo ngôn ngữ hiện tại)
  if (to.meta?.title) {
    document.title = `${i18n.t(to.meta.title)} | ReactJS Sample`
  }

  // chặn route cần đăng nhập:
  // ưu tiên `requiresAuth` của chính route hiện tại, nếu route đó không khai
  // báo thì lấy theo route cha gần nhất (xem resolveRequiresAuth).
  const requiresAuth = to.matched
    ? resolveRequiresAuth(to.matched)
    : !!to.meta?.requiresAuth

  if (requiresAuth) {
    const token = localStorage.getItem(TOKEN_KEY)
    if (!token) {
      return { name: 'login', query: { redirect: to.fullPath } }
    }
  }

  return true // cho phép đi tiếp
}

/* =========================================================================
 *  3. CHUYỂN ROUTES -> REACT ROUTER
 * ========================================================================= */

/** Tương đương <router-view /> — khai báo sớm vì buildRoute() dùng tới */
export const RouterView = () => <Outlet />

/**
 * Nhận diện "lazy loader" kiểu vue-router:  component: () => import('@/pages/Home')
 *
 *  - Class component (có prototype.isReactComponent) -> component tĩnh
 *  - Hàm KHÔNG tham số, thân hàm có gọi `import(...)` -> lazy loader
 *  - Còn lại (kể cả React.lazy / memo / forwardRef) -> component tĩnh
 *
 * LƯU Ý QUAN TRỌNG — vì sao KHÔNG neo regex vào đầu hàm:
 *  Khi `vite build`, Vite bọc mỗi `import()` động thành
 *      () => __vitePreload(() => import('./X.js'), __vite__mapDeps([...]))
 *  nên chuỗi hàm KHÔNG còn bắt đầu bằng `import(` nữa. Nếu regex chỉ khớp
 *  `import(` ở ngay đầu thân hàm thì trên bản build loader bị nhận nhầm là
 *  component tĩnh -> React nhận một hàm trả về Promise -> lỗi
 *  "Minified React error #31 ... [object Promise]" (chỉ xảy ra ở production).
 *  Vì vậy chỉ cần kiểm tra trong thân hàm CÓ lời gọi `import(` là đủ.
 */
const isLazyLoader = (c) => {
  if (typeof c !== 'function') return false
  if (c.prototype?.isReactComponent) return false // class component
  if (c.length > 0) return false // component luôn nhận props
  const src = Function.prototype.toString.call(c)
  // `import(` không đứng sau ký tự định danh / `$` / `.` -> là import động
  // (tránh khớp nhầm tên hàm kiểu `myimport(`)
  return /(?:^|[^\w$.])import\s*\(/.test(src)
}

/**
 * Chuẩn hoá `component` -> React component.
 * Nếu là loader thì tự bọc React.lazy (nhận cả module có `default` lẫn named export).
 */
const resolveComponent = (c) => {
  if (!c) return null
  if (!isLazyLoader(c)) return c
  return lazy(() => c().then((mod) => ({ default: mod?.default ?? mod })))
}

/** Chỗ hiển thị trong lúc chờ tải chunk của route lazy */
const LazyFallback = () => (
  <div className="loading-center">
    <Spin size="large" />
  </div>
)

/** Bọc <Suspense> cho route lazy (không ảnh hưởng route import tĩnh) */
const withSuspense = (element) => (
  <Suspense fallback={<LazyFallback />}>{element}</Suspense>
)

const withLayout = (element, meta) => {
  if (meta?.layout === 'blank') return element
  return <MainLayout>{element}</MainLayout>
}

/**
 * Chạy guard beforeEach trước khi render route (giống vue-router).
 *
 * LƯU Ý: `matched` được lấy từ CHÍNH url hiện tại (cha -> con), KHÔNG dùng
 * chuỗi route cục bộ của cấp đang render. Guard được lồng ở mọi cấp, nếu mỗi
 * cấp chỉ xét chuỗi cục bộ của nó thì route cha `requiresAuth: true` sẽ chặn
 * nhầm route con đã khai báo `requiresAuth: false` (vd: /medicine/catalog).
 * Lấy đủ chuỗi của url hiện tại giúp `requiresAuth` luôn được xét theo hướng
 * con -> cha (con ghi đè cha) ở bất kỳ cấp nào.
 */
const RouteGuard = ({ children }) => {
  const location = useLocation()
  const matched = findMatched(location.pathname)
  const result = beforeEach(
    {
      fullPath: location.pathname + location.search,
      matched,
      meta: mergeMeta(matched),
    },
    {},
  )
  if (result !== true) return <Navigate to={resolveLocation(result)} replace />
  return children
}

/** Truyền params trên url thành props cho component (giống props: true) */
const ComponentWithParams = ({ Component, ...rest }) => {
  const params = useParams()
  return <Component {...params} {...rest} />
}

/**
 * Tương đương `redirect` của vue-router — chuyển hướng ngay khi vào route.
 * Tính `to` ở thời điểm render (không phải lúc khai báo) để hàm redirect
 * nhận được route hiện tại, và để tránh phụ thuộc vòng khi khởi tạo module.
 */
const Redirect = ({ redirect, record }) => {
  const location = useLocation()
  const params = useParams()
  const [searchParams] = useSearchParams()

  const to = resolveRedirect(redirect, record, {
    path: location.pathname,
    fullPath: location.pathname + location.search,
    params,
    query: Object.fromEntries(searchParams.entries()),
    hash: location.hash,
  })

  // `replace` -> không để lại entry trong history (giống vue-router)
  return <Navigate to={to} replace />
}

/**
 * Chuyển 1 route record (có thể có `children`) -> object của react-router.
 * @param {object} r      route record trong mảng `routes`
 * @param {object} parent route cha (để gộp meta + biết layout)
 */
const buildRoute = (r, parent = null) => {
  const { path, component, props, meta, children, redirect } = r

  // meta hiệu lực = meta cha gộp meta con (con ghi đè cha)
  const mergedMeta = { ...(parent?.mergedMeta || {}), ...(meta || {}) }

  // guard chạy cho cả chuỗi cha -> con (giống vue-router)
  const matched = [...(parent?.matched || []), r]

  // route có `redirect` -> chuyển hướng, KHÔNG render component / layout nào
  if (redirect !== undefined) {
    return {
      path,
      element: (
        <RouteGuard>
          <Redirect redirect={redirect} record={r} />
        </RouteGuard>
      ),
    }
  }

  // component có thể là component tĩnh hoặc loader lazy (() => import(...))
  const Component = resolveComponent(component)

  // route cha không có component -> tự render <RouterView /> cho route con
  const inner = Component
    ? withSuspense(
        props ? (
          <ComponentWithParams Component={Component} />
        ) : (
          <Component />
        ),
      )
    : <RouterView />

  // layout chỉ bọc ở route gốc (route con nằm trong layout của cha)
  const element = parent ? inner : withLayout(inner, mergedMeta)

  return {
    path,
    element: <RouteGuard>{element}</RouteGuard>,
    children: children?.map((child) =>
      buildRoute(child, { ...r, mergedMeta, matched }),
    ),
  }
}

const buildRoutes = (list) => list.map((r) => buildRoute(r))

/* =========================================================================
 *  4. KHỞI TẠO ROUTER  — HASH HISTORY
 * ========================================================================= */

/**
 * Ghép path của route cha với path của route con -> path đầy đủ.
 *   joinPath('/medicine', 'detail/:id') -> '/medicine/detail/:id'
 *   joinPath('/medicine', '')           -> '/medicine'
 *   joinPath('/medicine', '/about')     -> '/about'   (con viết tuyệt đối)
 */
export const joinPath = (parentPath = '', childPath = '') => {
  if (childPath.startsWith('/')) return childPath
  const base = parentPath.replace(/\/+$/, '')
  const child = childPath.replace(/^\/+/, '')
  if (!child) return base || '/'
  return `${base}/${child}`
}

/**
 * Gắn `fullPath` (path đầy đủ, đã ghép cha + con) cho từng route record.
 * Nhờ vậy `resolveLocation({ name })` hoạt động đúng cả với route con.
 */
const attachFullPath = (list, parentPath = '') =>
  list.forEach((r) => {
    r.fullPath = joinPath(parentPath, r.path)
    if (r.children) attachFullPath(r.children, r.fullPath)
  })

attachFullPath(routes)

export const router = createHashRouter(buildRoutes(routes))

// Bổ sung API giống vue-router cho đối tượng router (dùng được ngoài component)
router.push = (to) => router.navigate(resolveLocation(to))
router.replace = (to) => router.navigate(resolveLocation(to), { replace: true })
router.back = () => router.navigate(-1)
router.go = (n) => router.navigate(n)

/** Chuyển { name, params, query } -> chuỗi url */
export const resolveLocation = (to) => {
  if (typeof to === 'string') return to

  const { name, params = {}, query = {} } = to || {}
  const record = findRouteByName(name)
  let path = record?.fullPath || '/'

  Object.entries(params).forEach(([k, v]) => {
    path = path.replace(`:${k}`, encodeURIComponent(v))
  })

  const qs = new URLSearchParams(query).toString()
  return qs ? `${path}?${qs}` : path
}

/**
 * Tương đương `resolveRelativePath` của vue-router.
 *
 * Tính path đích từ path của CHÍNH route đang khai báo `redirect`:
 *   resolveRelativePath('medicine', '/thuoc')          -> '/medicine'
 *   resolveRelativePath('',         '/medicine/list')  -> '/medicine/list'
 *   resolveRelativePath('../other', '/a/b/c')          -> '/a/other'
 *   resolveRelativePath('/about',   '/thuoc')          -> '/about'  (tuyệt đối)
 *
 * @param {string} to   giá trị redirect (chuỗi)
 * @param {string} from path đầy đủ của route đang khai báo redirect
 */
export const resolveRelativePath = (to, from) => {
  if (to.startsWith('/')) return to
  if (!to) return from

  const fromSegments = from.split('/')
  const toSegments = to.split('/')
  let position = fromSegments.length - 1
  let toPosition = 0
  let segment

  for (; toPosition < toSegments.length; toPosition++) {
    segment = toSegments[toPosition]
    // dừng ở segment đầu tiên không phải '.' / '..'
    if (segment !== '.' && segment !== '..') break
    // lùi 1 cấp; đã ở gốc thì thôi
    if (position === 1 || fromSegments[position] === '') continue
    position--
  }

  return (
    fromSegments.slice(0, position).join('/') +
    '/' +
    toSegments.slice(toPosition).join('/')
  )
}

/**
 * Tương đương `redirect` của vue-router -> chuỗi url cần chuyển tới.
 *
 *   redirect: '/medicine'                       -> '/medicine'
 *   redirect: 'medicine'                        -> tính tương đối theo route
 *   redirect: { name: 'medicine' }              -> tra fullPath theo name
 *   redirect: { name: 'x', params, query }      -> tra fullPath + thay params + query
 *   redirect: (to) => '/y'                      -> gọi hàm với route hiện tại
 *
 * @param {string|object|function} redirect giá trị khai báo trong route
 * @param {object} record  route record chứa `redirect` (để lấy fullPath)
 * @param {object} to      route hiện tại (truyền cho hàm redirect)
 */
export const resolveRedirect = (redirect, record, to = {}) => {
  // hàm: nhận route hiện tại, trả về location
  if (typeof redirect === 'function') {
    return resolveRedirect(redirect(to), record, to)
  }

  // object location: { name, params, query } hoặc { path, query }
  if (redirect && typeof redirect === 'object') {
    if (redirect.path) {
      const qs = new URLSearchParams(redirect.query || {}).toString()
      return qs ? `${redirect.path}?${qs}` : redirect.path
    }
    return resolveLocation(redirect)
  }

  // chuỗi: tính tương đối theo path đầy đủ của chính route đó
  return resolveRelativePath(String(redirect ?? ''), record?.fullPath || record?.path || '/')
}

/** Tìm route record theo `name` (đệ quy cả route con) */
export const findRouteByName = (name, list = routes) => {
  for (const r of list) {
    if (r.name === name) return r
    if (r.children) {
      const found = findRouteByName(name, r.children)
      if (found) return found
    }
  }
  return null
}

/** Tìm route record theo path hiện tại (để lấy name / meta) */
const findRoute = (pathname) => {
  for (const r of routes) {
    if (matchPath({ path: r.fullPath || r.path, end: true }, pathname)) return r
  }
  return null
}

/** Tìm CHUỖI route record khớp url hiện tại (cha -> con), giống route.matched */
const findMatched = (pathname) => {
  const matches = matchRoutes(routes, pathname) || []
  return matches.map((m) => m.route)
}

/* =========================================================================
 *  5. HOOKS  — dùng giống vue-router
 * ========================================================================= */

/** Tương đương useRouter() của vue-router */
export const useRouter = () => {
  const navigate = useNavigate()
  return {
    push: (to) => navigate(resolveLocation(to)),
    replace: (to) => navigate(resolveLocation(to), { replace: true }),
    back: () => navigate(-1),
    go: (n) => navigate(n),
    resolve: resolveLocation,
  }
}

/** Tương đương useRoute() của vue-router */
export const useRoute = () => {
  const location = useLocation()
  const params = useParams()
  const [searchParams] = useSearchParams()
  const matched = findMatched(location.pathname)
  const record = matched[matched.length - 1] || findRoute(location.pathname)

  return {
    path: location.pathname,
    fullPath: location.pathname + location.search + location.hash,
    name: record?.name,
    meta: mergeMeta(matched),
    matched, // chuỗi route record cha -> con (giống vue-router)
    params,
    query: Object.fromEntries(searchParams.entries()),
    hash: location.hash,
  }
}

/* =========================================================================
 *  6. COMPONENT GỐC
 * ========================================================================= */

/** Tương đương <router-link :to="..."> */
export const RouterLink = ({ to, children, ...rest }) => {
  const navigate = useNavigate()
  const href = resolveLocation(to)
  return (
    <a
      href={`#${href}`}
      onClick={(e) => {
        e.preventDefault()
        navigate(href)
      }}
      {...rest}
    >
      {children}
    </a>
  )
}

/** Component gốc gắn vào App */
export const AppRouter = () => <RouterProvider router={router} />

export { Navigate }
export default router
