/**
 * /store/index.js
 * ---------------------------------------------------------------------------
 * Khai báo STATE INSTANCE (store của Redux Toolkit).
 *
 * Cách dùng trong component:
 *   import { useAppDispatch, useAppSelector, mutations } from '@/store'
 *
 *   const counter = useAppSelector((s) => s.counter)
 *   const dispatch = useAppDispatch()
 *   dispatch(mutations.increase(1))
 *
 * `mutations` export ở đây là ACTION CREATOR (cùng tên với reducer trong
 * mutations.js) nên gọi được trực tiếp: mutations.increase(1) -> action.
 */

import { configureStore, createSlice } from '@reduxjs/toolkit'
import { useDispatch, useSelector } from 'react-redux'
import { state as initialState } from './state'
import { mutations as reducers } from './mutations'
import { storage } from '@/utils'

/**
 * Trạng thái THU GỌN SIDEBAR được ghi nhớ qua các lần tải lại trang (F5):
 *  - Lúc khởi tạo store: đọc giá trị đã lưu trong localStorage (nếu có).
 *  - Mỗi khi giá trị đổi: lưu lại (xem store.subscribe bên dưới).
 * Dùng chung helper `storage` ở src/utils/index.js (prefix reactjs_sample_)
 * giống cách src/lang/index.js và src/utils/theme.js đang lưu lựa chọn.
 */
const COLLAPSED_KEY = 'collapsed'

/**
 * Bọc object state + các mutations thành 1 slice duy nhất.
 * Nhờ vậy mọi key trong state.js đều nằm phẳng ở root của store
 * (state.counter, state.token ...) giống hệt Vuex.
 */
const appSlice = createSlice({
  name: 'app',
  initialState: {
    ...initialState,
    collapsed: storage.get(COLLAPSED_KEY, initialState.collapsed),
  },
  reducers,
})

/**
 * Action creator dùng để dispatch: mutations.increase(1), mutations.setToken('x') ...
 * (tên giữ nguyên như trong mutations.js để code component không phải đổi)
 */
export const mutations = appSlice.actions

/** Alias cũ, giữ để tương thích */
export const actions = appSlice.actions

export const store = configureStore({
  reducer: appSlice.reducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      // state chứa dữ liệu thuần -> tắt check để tránh warning không cần thiết
      serializableCheck: false,
    }),
  devTools: import.meta.env.MODE !== 'production',
})

// Ghi nhớ trạng thái thu gọn sidebar mỗi khi nó thay đổi
store.subscribe(() => {
  storage.set(COLLAPSED_KEY, store.getState().collapsed)
})

/** Đưa toàn bộ state về mặc định */
export const resetStore = () => store.dispatch(mutations.resetState(initialState))

/** Lấy state hiện tại ở ngoài component: getState().counter */
export const getState = () => store.getState()

// ---- hook tiện dụng --------------------------------------------------------
export const useAppDispatch = () => useDispatch()
export const useAppSelector = useSelector

export default store
