/**
 * /model/http.js
 * ---------------------------------------------------------------------------
 * Định nghĩa các hàm gọi HTTP bằng axios: post, get, postfile, getfile.
 *
 * - Tự động gắn token (nếu có) vào header Authorization.
 * - Tự động bắt lỗi và chuẩn hoá response trả về.
 * - Base URL lấy từ biến môi trường VITE_API_BASE_URL (xem file .env).
 */

import axios from 'axios'
import { message } from 'antd'

const BASE_URL = import.meta.env.VITE_API_BASE_URL || '/api'
const TIMEOUT = Number(import.meta.env.VITE_API_TIMEOUT || 30000)
const TOKEN_KEY = import.meta.env.VITE_TOKEN_KEY || 'reactjs_sample_token'

// ---- axios instance --------------------------------------------------------
const instance = axios.create({
  baseURL: BASE_URL,
  timeout: TIMEOUT,
  headers: { 'Content-Type': 'application/json' },
})

// ---- request interceptor: gắn token ---------------------------------------
instance.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem(TOKEN_KEY)
    if (token) config.headers.Authorization = `Bearer ${token}`
    return config
  },
  (error) => Promise.reject(error),
)

// ---- response interceptor: bóc data + bắt lỗi -----------------------------
instance.interceptors.response.use(
  (response) => response,
  (error) => {
    const status = error?.response?.status
    const msg =
      error?.response?.data?.message ||
      error?.message ||
      'Có lỗi xảy ra khi gọi API'

    if (status === 401) {
      localStorage.removeItem(TOKEN_KEY)
      message.error('Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại')
    } else if (status === 403) {
      message.error('Bạn không có quyền thực hiện thao tác này')
    } else if (status >= 500) {
      message.error('Lỗi máy chủ, vui lòng thử lại sau')
    } else if (!error.response) {
      message.error('Không kết nối được tới máy chủ')
    } else {
      message.error(msg)
    }

    return Promise.reject(error)
  },
)

/** Bóc tách dữ liệu trả về: ưu tiên response.data */
const unwrap = (response) => response?.data ?? response

/* =========================================================================
 *  CÁC HÀM PUBLIC
 * ========================================================================= */

/**
 * POST JSON
 * @param {string} url     đường dẫn api (vd: '/auth/login')
 * @param {object} data    body json
 * @param {object} config  config axios bổ sung (headers, params ...)
 */
export const post = async (url, data = {}, config = {}) => {
  const response = await instance.post(url, data, config)
  return unwrap(response)
}

/**
 * GET
 * @param {string} url     đường dẫn api (vd: '/medicine/list')
 * @param {object} params  query string dạng object
 * @param {object} config  config axios bổ sung
 */
export const get = async (url, params = {}, config = {}) => {
  const response = await instance.get(url, { params, ...config })
  return unwrap(response)
}

/**
 * POST FILE (upload) — multipart/form-data
 * @param {string} url        đường dẫn api
 * @param {FormData|object} data  FormData hoặc object { file, ...fields }
 * @param {function} onUploadProgress  callback theo dõi tiến trình (0..100)
 */
export const postfile = async (url, data = {}, onUploadProgress) => {
  const formData = data instanceof FormData ? data : toFormData(data)

  const response = await instance.post(url, formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
    onUploadProgress: (e) => {
      if (typeof onUploadProgress === 'function' && e.total) {
        onUploadProgress(Math.round((e.loaded * 100) / e.total))
      }
    },
  })
  return unwrap(response)
}

/**
 * GET FILE (download) — trả về Blob
 * @param {string} url     đường dẫn api
 * @param {object} params  query string
 * @param {string} fileName  tên file lưu về máy (tuỳ chọn)
 */
export const getfile = async (url, params = {}, fileName) => {
  const response = await instance.get(url, {
    params,
    responseType: 'blob',
  })

  // Tự động tải file xuống nếu có tên file
  if (fileName) {
    const blobUrl = window.URL.createObjectURL(new Blob([response.data]))
    const link = document.createElement('a')
    link.href = blobUrl
    link.download = fileName
    document.body.appendChild(link)
    link.click()
    link.remove()
    window.URL.revokeObjectURL(blobUrl)
  }

  return response.data
}

/** Helper: object -> FormData (dùng cho postfile) */
const toFormData = (obj = {}) => {
  const fd = new FormData()
  Object.entries(obj).forEach(([key, value]) => {
    if (value === undefined || value === null) return
    if (Array.isArray(value)) {
      value.forEach((v) => fd.append(key, v))
    } else if (value instanceof File || value instanceof Blob) {
      fd.append(key, value)
    } else if (typeof value === 'object') {
      fd.append(key, JSON.stringify(value))
    } else {
      fd.append(key, value)
    }
  })
  return fd
}

export { instance, BASE_URL, TOKEN_KEY }
export default { post, get, postfile, getfile, instance }
