/**
 * /components/MainLayout.jsx
 * ---------------------------------------------------------------------------
 * Layout chính: Sidebar menu (sinh tự động từ routes) + Header + Content.
 */

import React, { useMemo, useRef, useState } from 'react'
import { Layout, Menu, Button, Avatar, Space, Typography, Tooltip, FloatButton } from 'antd'
import {
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  HomeOutlined,
  InfoCircleOutlined,
  MedicineBoxOutlined,
  AppstoreOutlined,
  UnorderedListOutlined,
  UploadOutlined,
  UserOutlined,
  LogoutOutlined,
  FileTextOutlined,
  SafetyCertificateOutlined,
  ApiOutlined,
  ProfileOutlined,
} from '@ant-design/icons'

import { routes, useRouter, useRoute } from '@/router'
import { useAppDispatch, useAppSelector, mutations } from '@/store'
import { getters } from '@/store/getters'
import { useI18n } from '@/lang'
import LanguageSwitcher from '@/components/LanguageSwitcher'
import ThemeSwitcher from '@/components/ThemeSwitcher'

const { Header, Sider, Content, Footer } = Layout
const { Text } = Typography

const ICONS = {
  home: <HomeOutlined />,
  info: <InfoCircleOutlined />,
  readme: <FileTextOutlined />,
  rule: <SafetyCertificateOutlined />,
  hook: <ApiOutlined />,
  note: <ProfileOutlined />,
  medicine: <MedicineBoxOutlined />,
  catalog: <AppstoreOutlined />,
  list: <UnorderedListOutlined />,
  upload: <UploadOutlined />,
}

/**
 * Label của item menu: chỉ hiện Tooltip (Ant Design) khi nội dung bị cắt
 * (tràn -> có dấu "..."). Kiểm tra lúc hover để biết chắc có tràn hay không.
 */
const MenuLabel = ({ text }) => {
  const ref = useRef(null)
  const [overflow, setOverflow] = useState(false)

  const checkOverflow = () => {
    const el = ref.current
    if (el) setOverflow(el.scrollWidth > el.clientWidth)
  }

  return (
    <Tooltip title={overflow ? text : null} placement="right">
      <span ref={ref} className="app-menu-label" onMouseEnter={checkOverflow}>
        {text}
      </span>
    </Tooltip>
  )
}

/**
 * Sinh menu NHIỀU CẤP từ mảng `routes` (đệ quy theo `children`).
 *  - Bỏ route không có `name`, route `meta.hidden`, route layout 'blank'
 *    và route chỉ để `redirect` (không có trang nào để hiển thị).
 *  - Route có children -> item cha (submenu).
 *  - Route lá -> item bấm được.
 *  - `key` của item là `name` của route (duy nhất, kể cả route index có
 *    path trùng cha); khi bấm sẽ tra ra `fullPath` để điều hướng.
 */
const buildMenuItems = (list, t) =>
  list
    .filter(
      (r) =>
        r.name &&
        r.redirect === undefined &&
        !r.meta?.hidden &&
        r.meta?.layout !== 'blank',
    )
    .map((r) => {
      const children = r.children ? buildMenuItems(r.children, t) : []
      const item = {
        key: r.name,
        icon: ICONS[r.meta?.icon] || null,
        label: <MenuLabel text={t(r.meta?.title || r.name)} />,
      }
      // route cha có con -> submenu; nếu không còn con nào hiện thì thành item lá
      return children.length ? { ...item, children } : item
    })

/** Tra `name` -> `fullPath` để điều hướng khi bấm menu (đệ quy cả route con) */
const buildPathMap = (list, map = {}) => {
  list.forEach((r) => {
    if (r.name) map[r.name] = r.fullPath || r.path
    if (r.children) buildPathMap(r.children, map)
  })
  return map
}

/** Tập hợp key của các item đang có trên menu (đệ quy) */
const collectKeys = (items, set = new Set()) => {
  items.forEach((i) => {
    set.add(i.key)
    if (i.children) collectKeys(i.children, set)
  })
  return set
}

export { buildMenuItems, buildPathMap, collectKeys }

const MainLayout = ({ children }) => {
  const router = useRouter()
  const route = useRoute()
  const dispatch = useAppDispatch()
  const { t, locale } = useI18n()

  const collapsed = useAppSelector(getters.collapsed)
  const appName = useAppSelector(getters.appName)
  const userName = useAppSelector(getters.userName)
  const isLoggedIn = useAppSelector(getters.isLoggedIn)

  // Sinh menu từ routes (đệ quy cả route con nhiều cấp)
  // label lấy từ meta.title (khoá tiếng Việt) rồi dịch qua i18n
  const menuItems = useMemo(
    () => buildMenuItems(routes, t),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [t, locale],
  )

  // name -> fullPath, dùng để điều hướng khi bấm menu
  const pathMap = useMemo(() => buildPathMap(routes), [])

  // key đang chọn = route khớp url hiện tại (ưu tiên route con sâu nhất).
  // Nếu route hiện tại KHÔNG có trên menu (vd: meta.hidden như medicine-detail,
  // medicine-import, medicine-catalog-group) thì lấy tổ tiên GẦN NHẤT có trên
  // menu — nhờ vậy menu cha vẫn được đánh dấu là "đang dùng" (nhất là khi
  // sidebar thu nhỏ, người dùng không hover thì vẫn thấy được mục đang mở).
  const selectedKey = useMemo(() => {
    const own = route.name || route.path
    const keys = collectKeys(menuItems)
    if (keys.has(own)) return own
    const ancestors = (route.matched || [])
      .map((r) => r.name)
      .filter((k) => k && keys.has(k))
    return ancestors[ancestors.length - 1] || own
  }, [route.name, route.path, route.matched, menuItems])

  // mở sẵn submenu cha của route hiện tại (chỉ lấy key có trên menu)
  const openKeys = useMemo(() => {
    const keys = collectKeys(menuItems)
    return (route.matched || [])
      .map((r) => r.name)
      .filter((k) => k && keys.has(k))
  }, [route.matched, menuItems])

  const handleLogout = () => {
    dispatch(mutations.logout())
    localStorage.removeItem(import.meta.env.VITE_TOKEN_KEY || 'reactjs_sample_token')
    router.push('/login')
  }

  return (
    <Layout className="app-layout">
      <Sider trigger={null} collapsible collapsed={collapsed} theme="dark">
        <div className="app-logo">
          <MedicineBoxOutlined className="app-logo-icon" />
          {!collapsed && <span>{appName}</span>}
        </div>
        <Menu
          theme="dark"
          mode="inline"
          selectedKeys={[selectedKey]}
          defaultOpenKeys={openKeys}
          items={menuItems}
          onClick={({ key }) => router.push(pathMap[key] || key)}
        />
      </Sider>

      <Layout>
        <Header className="app-header">
          <Button
            type="text"
            className="app-header-toggle"
            icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
            onClick={() => dispatch(mutations.setCollapsed(!collapsed))}
          />

          <Space size="middle">
            <Text type="secondary">{t(route.meta?.title)}</Text>
            <ThemeSwitcher />
            <LanguageSwitcher />
            <Avatar icon={<UserOutlined />} />
            <Text>{userName}</Text>
            {isLoggedIn && (
              <Button
                type="text"
                danger
                icon={<LogoutOutlined />}
                onClick={handleLogout}
              >
                {t('Đăng xuất')}
              </Button>
            )}
          </Space>
        </Header>

        <Content className="app-content">{children}</Content>

        <Footer className="app-footer">
          {t('ReactJS Sample ©{{year}} — Ant Design + Vite + Redux Toolkit', {
            year: new Date().getFullYear(),
          })+' '+t('Author: Đào Văn Tuyến dvtnkbnvn')}
        </Footer>
      </Layout>

      {/* nút cuộn lên đầu trang — Ant Design tự ẩn khi trang chưa đủ dài */}
      <FloatButton.BackTop
        className="app-back-top"
        tooltip={t('Lên đầu trang')}
        visibilityHeight={300}
      />
    </Layout>
  )
}

export default MainLayout
