/**
 * /store/mutations.js
 * ---------------------------------------------------------------------------
 * Khai báo các HÀM SET giá trị vào state (tương đương mutations của Vuex).
 *
 * LƯU Ý QUAN TRỌNG — đây là REDUCER của Redux Toolkit, không phải hàm thường:
 *  - Mỗi hàm nhận (state, action) và set trực tiếp lên draft state (Immer).
 *  - Giá trị truyền vào khi dispatch nằm ở `action.payload`.
 *  - KHÔNG gọi trực tiếp các hàm này. Hãy dispatch action creator cùng tên
 *    được export từ '@/store':
 *
 *        import { useAppDispatch, mutations } from '@/store'
 *        dispatch(mutations.increase(1))
 *        dispatch(mutations.setToken('abc'))
 *        dispatch(mutations.setValue({ key: 'loading', value: true }))
 *
 *  - Đặt tên theo mẫu: set<Tên biến>  (setToken, setUserInfo, setLoading ...)
 */

import { state as initialState } from './state'

/** Lấy payload, trả về giá trị mặc định nếu không truyền */
const num = (payload, fallback) => {
  const n = Number(payload)
  return Number.isFinite(n) ? n : fallback
}

export const mutations = {
  /** set 1 key bất kỳ: dispatch(mutations.setValue({ key: 'counter', value: 1 })) */
  setValue: (state, action) => {
    const { key, value } = action.payload || {}
    if (key) state[key] = value
  },

  /** set nhiều key cùng lúc: dispatch(mutations.setValues({ loading: true, counter: 2 })) */
  setValues: (state, action) => {
    Object.assign(state, action.payload || {})
  },

  // ---- app ---------------------------------------------------------------
  setAppName: (state, action) => {
    state.appName = action.payload
  },
  setCollapsed: (state, action) => {
    state.collapsed = !!action.payload
  },

  // ---- auth --------------------------------------------------------------
  setToken: (state, action) => {
    state.token = action.payload || ''
  },
  setUserInfo: (state, action) => {
    state.userInfo = action.payload || null
  },
  logout: (state) => {
    state.token = ''
    state.userInfo = null
  },

  // ---- nghiệp vụ ---------------------------------------------------------
  setLoading: (state, action) => {
    state.loading = !!action.payload
  },
  setCounter: (state, action) => {
    state.counter = num(action.payload, 0)
  },
  increase: (state, action) => {
    state.counter += num(action.payload, 1)
  },
  decrease: (state, action) => {
    state.counter -= num(action.payload, 1)
  },

  setTodoList: (state, action) => {
    state.todoList = Array.isArray(action.payload) ? action.payload : []
  },
  pushTodo: (state, action) => {
    state.todoList.push(action.payload)
  },
  removeTodo: (state, action) => {
    state.todoList = state.todoList.filter((t) => t.id !== action.payload)
  },

  setMedicineList: (state, action) => {
    state.medicineList = Array.isArray(action.payload) ? action.payload : []
  },

  /** đưa state về giá trị ban đầu */
  resetState: (state, action) => {
    Object.assign(state, action.payload || initialState)
  },

  setTestMessage: (state, action) => {
    state.testMessage = action.payload||''
  },

}

export default mutations
