/**
 * /lang/index.js
 * ---------------------------------------------------------------------------
 * Khai báo OBJECT I18N — dùng giống vue-i18n.
 *
 *  - Từ điển nằm trong các file: vi_VN.js / en_US.js / zh_TW.js
 *  - Key của từ điển CHÍNH LÀ câu tiếng Việt:
 *        t('Trang chủ')  ->  'Home' (khi locale = en_US)
 *  - Hỗ trợ nội suy tham số:  t('Tổng: {{count}}', { count: 5 })
 *  - Tự lưu ngôn ngữ đã chọn vào localStorage.
 *
 *  Cách dùng trong component:
 *      import { useI18n } from '@/lang'
 *      const { t, locale, setLocale, availableLocales } = useI18n()
 *      <span>{t('Trang chủ')}</span>
 *
 *  Dùng ngoài component:
 *      import i18n from '@/lang'
 *      i18n.t('Trang chủ')
 *      i18n.setLocale('en_US')
 */

import { useSyncExternalStore } from 'react'
import vi_VN from './vi_VN'
import en_US from './en_US'
import zh_TW from './zh_TW'

/* =========================================================================
 *  1. DANH SÁCH NGÔN NGỮ
 * ========================================================================= */
export const messages = {
  vi_VN,
  en_US,
  zh_TW,
}

export const availableLocales = [
  { value: 'vi_VN', label: 'Tiếng Việt', flag: '🇻🇳' },
  { value: 'en_US', label: 'English', flag: '🇺🇸' },
  { value: 'zh_TW', label: '繁體中文', flag: '🇹🇼' },
]

export const DEFAULT_LOCALE = 'vi_VN'
const STORAGE_KEY = 'reactjs_sample_locale'

/* =========================================================================
 *  2. HÀM DỊCH
 * ========================================================================= */

/**
 * Nội suy tham số: interpolate('Tổng: {{count}}', { count: 5 }) -> 'Tổng: 5'
 */
const interpolate = (text, params) => {
  if (!params || typeof text !== 'string') return text
  return text.replace(/\{\{\s*(\w+)\s*\}\}/g, (match, key) =>
    params[key] !== undefined && params[key] !== null ? String(params[key]) : match,
  )
}

/**
 * Dịch 1 key.
 * @param {string} key     câu tiếng Việt (khoá tra cứu)
 * @param {object} params  tham số nội suy
 * @param {string} locale  ngôn ngữ muốn dịch (mặc định: ngôn ngữ hiện tại)
 */
export const translate = (key, params, locale) => {
  const lang = locale || i18n.locale
  const dict = messages[lang] || messages[DEFAULT_LOCALE]

  // 1) tìm trong từ điển ngôn ngữ hiện tại
  let text = dict?.[key]

  // 2) không có -> fallback sang tiếng Việt (key gốc)
  if (text === undefined) text = messages[DEFAULT_LOCALE]?.[key]

  // 3) vẫn không có -> trả về chính key
  if (text === undefined) text = key

  return interpolate(text, params)
}

/* =========================================================================
 *  3. OBJECT I18N
 * ========================================================================= */
const listeners = new Set()

const readStoredLocale = () => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    return messages[saved] ? saved : DEFAULT_LOCALE
  } catch {
    return DEFAULT_LOCALE
  }
}

export const i18n = {
  /** ngôn ngữ hiện tại */
  locale: readStoredLocale(),

  /** ngôn ngữ mặc định (dùng khi key không tồn tại) */
  fallbackLocale: DEFAULT_LOCALE,

  /** danh sách ngôn ngữ */
  availableLocales,

  /** toàn bộ từ điển */
  messages,

  /** hàm dịch — t('Trang chủ'), t('Tổng: {{count}}', { count: 5 }) */
  t(key, params) {
    return translate(key, params, this.locale)
  },

  /** đổi ngôn ngữ */
  setLocale(locale) {
    if (!messages[locale] || locale === this.locale) return
    this.locale = locale
    try {
      localStorage.setItem(STORAGE_KEY, locale)
    } catch {
      /* ignore */
    }
    document.documentElement.lang = locale.replace('_', '-')
    listeners.forEach((fn) => fn())
  },

  /** đăng ký theo dõi thay đổi ngôn ngữ (dùng nội bộ cho hook) */
  subscribe(fn) {
    listeners.add(fn)
    return () => listeners.delete(fn)
  },

  /** lấy ngôn ngữ hiện tại (dùng cho useSyncExternalStore) */
  getLocale() {
    return this.locale
  },
}

/* =========================================================================
 *  4. HOOK  — dùng giống useI18n() của vue-i18n
 * ========================================================================= */
export const useI18n = () => {
  const locale = useSyncExternalStore(
    (cb) => i18n.subscribe(cb),
    () => i18n.getLocale(),
    () => DEFAULT_LOCALE,
  )

  return {
    /** hàm dịch */
    t: (key, params) => translate(key, params, locale),
    /** ngôn ngữ hiện tại */
    locale,
    /** đổi ngôn ngữ */
    setLocale: (l) => i18n.setLocale(l),
    /** danh sách ngôn ngữ */
    availableLocales,
    /** toàn bộ từ điển */
    messages,
  }
}

export default i18n
