/**
 * /components/LanguageSwitcher.jsx
 * ---------------------------------------------------------------------------
 * Dropdown chọn ngôn ngữ (vi_VN / en_US / zh_TW).
 */

import React from 'react'
import { Dropdown, Button, Space, Typography } from 'antd'
import { GlobalOutlined, DownOutlined } from '@ant-design/icons'

import { useI18n } from '@/lang'

const { Text } = Typography

const LanguageSwitcher = ({ showLabel = true }) => {
  const { t, locale, setLocale, availableLocales } = useI18n()

  const current =
    availableLocales.find((l) => l.value === locale) || availableLocales[0]

  const items = availableLocales.map((l) => ({
    key: l.value,
    label: (
      <Space>
        <span>{l.flag}</span>
        <span>{l.label}</span>
      </Space>
    ),
  }))

  return (
    <Dropdown
      menu={{
        items,
        selectable: true,
        selectedKeys: [locale],
        onClick: ({ key }) => setLocale(key),
      }}
      trigger={['click']}
    >
      <Button type="text">
        <Space size={6}>
          <GlobalOutlined />
          {showLabel && <Text>{current.label}</Text>}
          <DownOutlined className="lang-switcher-caret" />
        </Space>
      </Button>
    </Dropdown>
  )
}

export default LanguageSwitcher
