/**
 * /store/getters.js
 * ---------------------------------------------------------------------------
 * Khai báo các HÀM GET giá trị từ state (tương đương getters của Vuex).
 *
 * Quy ước:
 *  - Mỗi getter nhận (state) và trả về giá trị đã tính toán / format.
 *  - Dùng trong component qua hook useGetters() hoặc useAppSelector.
 */

import { useAppSelector } from './index'

export const getters = {
  // ---- app ---------------------------------------------------------------
  appName: (state) => state.appName,
  appVersion: (state) => state.appVersion,
  collapsed: (state) => state.collapsed,

  // ---- auth --------------------------------------------------------------
  token: (state) => state.token,
  userInfo: (state) => state.userInfo,
  isLoggedIn: (state) => !!state.token,
  userName: (state) => state.userInfo?.name || 'Khách',

  // ---- nghiệp vụ ---------------------------------------------------------
  loading: (state) => state.loading,
  counter: (state) => state.counter,
  counterText: (state) => `Giá trị hiện tại: ${state.counter}`,

  todoList: (state) => state.todoList,
  todoCount: (state) => state.todoList.length,
  todoDoneCount: (state) => state.todoList.filter((t) => t.done).length,

  medicineList: (state) => state.medicineList,
  medicineCount: (state) => state.medicineList.length,
  testMessage:(state)=>state.testMessage ,
}

/**
 * Hook lấy nhanh nhiều getter cùng lúc:
 *   const { counter, isLoggedIn } = useGetters()
 *   const { counter } = useGetters(['counter'])
 *
 * Chỉ gọi useAppSelector MỘT lần (không gọi hook trong vòng lặp) để không vi
 * phạm Rules of Hooks khi danh sách `keys` thay đổi giữa các lần render.
 */
export const useGetters = (keys) => {
  const names = Array.isArray(keys) ? keys : Object.keys(getters)
  const values = useAppSelector((state) => names.map((key) => getters[key](state)))
  return Object.fromEntries(names.map((key, i) => [key, values[i]]))
}

export default getters
