/**
 * /utils/theme.js
 * ---------------------------------------------------------------------------
 * Quản lý THEME (dark / light) — cùng phong cách với src/lang/index.js.
 *
 *  - Lưu lựa chọn vào localStorage.
 *  - Gắn `data-theme` lên <html> để CSS trong src/assets/theme.css đổi biến.
 *  - Thông báo cho component qua useSyncExternalStore (hook useTheme).
 *
 *  Dùng trong component:
 *      import { useTheme } from '@/utils/theme'
 *      const { isDark, toggleTheme } = useTheme()
 *
 *  Dùng ngoài component:
 *      import theme from '@/utils/theme'
 *      theme.setTheme('dark')
 */

import { useSyncExternalStore } from 'react'

export const THEMES = ['light', 'dark']
export const DEFAULT_THEME = 'light'
const STORAGE_KEY = 'reactjs_sample_theme'

const listeners = new Set()

/** Đọc theme đã lưu; nếu chưa có thì theo cài đặt hệ điều hành */
const readStoredTheme = () => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (THEMES.includes(saved)) return saved
    if (
      typeof window !== 'undefined' &&
      window.matchMedia &&
      window.matchMedia('(prefers-color-scheme: dark)').matches
    ) {
      return 'dark'
    }
  } catch {
    /* ignore */
  }
  return DEFAULT_THEME
}

/** Gắn theme lên <html> để CSS áp dụng */
const applyTheme = (theme) => {
  if (typeof document === 'undefined') return
  document.documentElement.setAttribute('data-theme', theme)
  document.documentElement.style.colorScheme = theme
}

export const theme = {
  /** theme hiện tại */
  current: readStoredTheme(),

  /** danh sách theme */
  themes: THEMES,

  /** đổi theme */
  setTheme(next) {
    if (!THEMES.includes(next) || next === this.current) return
    this.current = next
    applyTheme(next)
    try {
      localStorage.setItem(STORAGE_KEY, next)
    } catch {
      /* ignore */
    }
    listeners.forEach((fn) => fn())
  },

  /** đảo theme light <-> dark */
  toggleTheme() {
    this.setTheme(this.current === 'dark' ? 'light' : 'dark')
  },

  /** đăng ký theo dõi thay đổi (dùng nội bộ cho hook) */
  subscribe(fn) {
    listeners.add(fn)
    return () => listeners.delete(fn)
  },

  /** lấy theme hiện tại (dùng cho useSyncExternalStore) */
  getTheme() {
    return this.current
  },
}

// áp dụng ngay khi module được nạp
applyTheme(theme.current)

/** Hook dùng trong component */
export const useTheme = () => {
  const current = useSyncExternalStore(
    (cb) => theme.subscribe(cb),
    () => theme.getTheme(),
    () => DEFAULT_THEME,
  )

  return {
    theme: current,
    isDark: current === 'dark',
    setTheme: (t) => theme.setTheme(t),
    toggleTheme: () => theme.toggleTheme(),
  }
}

export default theme
